package main

import (
	"fmt"
	"sort"
)

func main() {
	var n, m int
	fmt.Scan(&n, &m)

	a := make([]int, m)
	for i := 0; i < m; i++ {
		fmt.Scan(&a[i])
	}

	sort.Ints(a)

	if n > m {
		fmt.Print(0)
		return
	}
	if n == m {
		fmt.Print(1)
		return
	}

	b := []int{}
	count := 1
	for i := 1; i < m; i++ {
		if a[i] == a[i-1] {
			count++
		} else {
			b = append(b, count)
			count = 1
		}
	}
	b = append(b, count)

	sort.Ints(b)

	x := 0
	for i := 1; i <= 101; i++ {
		s := 0
		for _, v := range b {
			s += v / i
		}
		if s >= n {
			x = i
		}
	}

	fmt.Print(x)
}

